export const ErrorFallback = ({ error, resetErrorBoundary, InteractiveMessageType }) => {
  const metricName = InteractiveMessageType + "_ERROR"
  if (window.connect && window.connect.csmService) {
    window.connect.csmService.addCountAndErrorMetric(metricName, CSM_CATEGORY.UI, false);
  }
  console.warn("Render Error for:", error);
  return (
    <div role="alert">
      <p>Something went wrong</p>
      <button onClick={resetErrorBoundary}>Reload Editor</button>
    </div>
  )
}

const ParticipantMessage = memo((props) => {
  const {
    messageDetails,
    incomingMsgStyle,
    outgoingMsgStyle,
    mediaOperations,
    isLatestMessage,
    shouldShowMessageReceipts,
    sendReadReceipt,
  } = props;

  const [inView, setInView] = useState(false);
  const [isVisible, setIsVisible] = useState(false);
  const [animate, setAnimate] = useState(true);

  const csmService = window.connect && window.connect.csmService ? window.connect.csmService : undefined;

  const timestampToDisplayable = (timestamp) => {
    const d = new Date(0);
    d.setUTCSeconds(timestamp);
    const today = new Date().toDateString();
    const thatDay = new Date(timestamp * 1000).toDateString();
    const option = { hour: "numeric", minute: "numeric" };
    if (today === thatDay) {
      return d.toLocaleTimeString([], option);
    }
    return d.toLocaleTimeString([], {
      ...option,
      weekday: "short",
      month: "short",
      day: "numeric",
    });
  };

  const renderHeader = () => {
    const isOutgoingMsg = messageDetails.transportDetails.direction === Direction.Outgoing;
    const displayName = messageDetails.displayName || (isOutgoingMsg ? "Customer" : "Agent");
    const transportDetails = messageDetails.transportDetails;
    const statusStringPrefix = "connect-chat-transport-status-";

    let transportStatusElement = <React.Fragment />;
    switch (transportDetails.status) {
      case Status.Sending:
        transportStatusElement = (
          <React.Fragment>
            <StatusText>
              <span>
                <FormattedMessage
                    id={statusStringPrefix + "sending"}
                    defaultMessage="Sending"
                />
              </span>
            </StatusText>
          </React.Fragment>
        );
        break;
      case Status.SendSuccess:
        transportStatusElement = <React.Fragment>{timestampToDisplayable(transportDetails.sentTime, isOutgoingMsg)}</React.Fragment>;
        break;
      case Status.SendFailed:
        transportStatusElement = (
          <ErrorText>
            <Icon />
            <span>
              <FormattedMessage
                  id={statusStringPrefix + "sendFailed"}
                  defaultMessage="Failed to send! "
              />
            </span>
          </ErrorText>
        );
        break;
      default:
        transportStatusElement = <React.Fragment />;
    }
   
    return (
      <Header direction={messageDetails.transportDetails.direction}>
        <Header.Sender>
          <FormattedMessage
              id={displayName || "DISPLAY_NAME_MISSING"}
              defaultMessage={displayName}
          />
        </Header.Sender>
        <Header.Status>{transportStatusElement}</Header.Status>
      </Header>
    );
  };

  const renderMessageReceipts = () => {
    const {
      lastReadReceipt = true,
      lastDeliveredReceipt = true,
      transportDetails: { messageReceiptType, direction } = {},
    } = messageDetails;
    if (direction !== Direction.Outgoing || !messageReceiptType) {
      return null;
    }
    return (
      <React.Fragment>
        <Footer.MessageReceipt>
          {lastReadReceipt && <FormattedMessage
              id="connect-chat-read-receipt"
              defaultMessage="Read"
              aria-live="polite"
          />}
          {lastDeliveredReceipt && <FormattedMessage
              id="connect-chat-delivered-receipt"
              defaultMessage="Delivered"
              aria-live="polite"
          />}
        </Footer.MessageReceipt>
      </React.Fragment>
    );
  };

  const visibilityChangeListener = () => {
    const isVisible = document.visibilityState === "visible";
    setIsVisible(isVisible);
  };

  useEffect(() => {
    //Bug-Fix: In Firefox react-intersection-observer is not able to identify if a page is active or minimized.
    visibilityChangeListener();
    document.addEventListener(
      "visibilitychange",
      visibilityChangeListener,
    );
    return () => {
      document.removeEventListener(
        "visibilitychange",
        visibilityChangeListener,
      );
    };
  }, []);

  useEffect(() => {
    const {
      transportDetails: { direction },
      type,
      id,
      participantRole,
    } = messageDetails;
    //Note: type valid values: https://docs.aws.amazon.com/connect-participant/latest/APIReference/API_Item.html#connectparticipant-Type-Item-Type
    if (
      inView &&
      isVisible &&
      modelUtils.isTypeMessageOrAttachment(type) &&
      modelUtils.isParticipantAgentOrCustomer(participantRole) &&
      direction === Direction.Incoming
    ) {
      sendReadReceipt(
        id,
        type === ATTACHMENT_MESSAGE ? { disableThrottle: true } : {},
      );
    }
  }, [inView, isVisible, messageDetails, sendReadReceipt]);

  useEffect(() => {
    if (animate) {
      const timer = setTimeout(() => setAnimate(false), 500);
      return () => clearTimeout(timer);
    }
  }, [animate]);

  const triggerCountMetric = (csmType) => {
    if (csmService) {
      csmService.addCountMetric(csmType, CSM_CATEGORY.UI);
    }
  };

  let { direction, error } = messageDetails.transportDetails;
  const messageStyle =
    direction === Direction.Outgoing
      ? outgoingMsgStyle
      : incomingMsgStyle;

  //Hack to simulate ChatJS response with attachment content types
  const bodyStyleConfig = {};
  if (
    isLatestMessage &&
    messageDetails.content &&
    messageDetails.content.type ===
      ContentType.MESSAGE_CONTENT_TYPE.INTERACTIVE_MESSAGE
  ) {
    bodyStyleConfig.hideDirectionArrow = true;
    bodyStyleConfig.removePadding = true;

    const { templateType } = JSON.parse(messageDetails.content.data);
    if (templateType === InteractiveMessageType.VIEW_RESOURCE || templateType === InteractiveMessageType.QUICK_REPLY || templateType === InteractiveMessageType.CAROUSEL) {
      bodyStyleConfig.childWillAddBackground = true;
      bodyStyleConfig.hideDirectionArrow = true;
    }
  } 
  let content, contentType;
  if (messageDetails.type === ATTACHMENT_MESSAGE) {
    //Use Attachments data as content if available
    //If an attachment message does not have this data, it means the upload was rejected
    if (
      messageDetails.Attachments &&
      messageDetails.Attachments.length > 0
    ) {
      content = messageDetails.Attachments[0];
      contentType = content.ContentType;
      if (content.Status === AttachmentStatus.REJECTED && error === undefined) {
        error = {
          message: "Attachment was rejected."
        }
      }
    } else {

  
      contentType = messageDetails.content.type;
    }
  } else {
    content = messageDetails.content.data;
    contentType = messageDetails.content.type;
    if (!shouldDisplayMessageForType(contentType)) {
      return null;
    }
  }

  return (
    <CSSTransition key={messageDetails.id} timeout={500} classNames="message">
      <MessageBox animate={animate} data-testid="main-message">
        {renderHeader()}
        <InView onChange={(inView) => setInView(inView)}>
          {({ ref }) => (
            <Body
              data-testid="message-body"
              direction={direction}
              messageStyle={messageStyle}
              {...bodyStyleConfig}
              ref={isLatestMessage ? ref : null}
            >
              {renderContent(content, contentType, mediaOperations, isLatestMessage, triggerCountMetric)}
            </Body>
          )}
        </InView>
        <Footer>
          {renderMessageReceipts()}
        </Footer>
        {error && renderTransportError(error)}
      </MessageBox>
    </CSSTransition>
  );
});

ParticipantMessage.propTypes = {
  messageDetails: PT.object.isRequired,
  incomingMsgStyle: PT.object,
  outgoingMsgStyle: PT.object,
  mediaOperations: PT.object,
  isLatestMessage: PT.bool,
  shouldShowMessageReceipts: PT.bool,
  sendReadReceipt: PT.func.isRequired,
};

const renderContent = (content, contentType, mediaOperations, isLatestMessage, triggerCountMetric) => {
  

  if (contentType === ContentType.MESSAGE_CONTENT_TYPE.INTERACTIVE_MESSAGE) {
    const { data, templateType } = JSON.parse(content);
    if (isLatestMessage) {
      triggerCountMetric(templateType + CSM_CONSTANTS.RENDER_INTERACTIVE_MESSAGE)
      return (
        <ErrorBoundary fallback={<ErrorFallback InteractiveMessageType={templateType}/>} >
          <InteractiveMessage
            content={data.content}
            templateType={templateType}
            addMessage={mediaOperations.addMessage}
            textInputRef={mediaOperations.textInputRef}
          />
        </ErrorBoundary>
      )
    }
    triggerCountMetric(CSM_CONSTANTS.RENDER_RICH_MESSAGE)
    return <RichMessageRenderer content={data.content.title} />
  }
  if (contentType === ContentType.MESSAGE_CONTENT_TYPE.INTERACTIVE_RESPONSE &&
    JSON.parse(content).templateType === InteractiveMessageType.VIEW_RESOURCE) {
    // this is a view response, render accordingly
    let { action, data } = JSON.parse(content);
    if (!action.trim() && data)
      action = data.content;
    return <PlainTextMessage content={action} />
  }

  if (contentType === ContentType.MESSAGE_CONTENT_TYPE.TEXT_MARKDOWN) {
    triggerCountMetric(CSM_CONSTANTS.RENDER_RICH_MESSAGE)
    return <RichMessageRenderer content={content} />
  }
  triggerCountMetric(CSM_CONSTANTS.RENDER_PLAIN_MESSAGE)
  if (isCarouselSelectionMessage(content)) {
    const carouselAndNestedPickerTitle = formatCarouselInteractiveSelection(content);
    return <PlainTextMessage content={carouselAndNestedPickerTitle} />
  }

  // Handle attachment content
  if (typeof content === 'object' && content.ContentType && content.AttachmentName) {
    return (
      <div>
        <span>
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor" className="bi bi-paperclip" viewBox="0 0 16 16">
            <path d="M6.354 5.5H6.5a.5.5 0 0 1 .5.5v6a2.5 2.5 0 0 0 5 0v-6a3.5 3.5 0 0 0-7 0v6a1.5 1.5 0 0 0 3 0v-6a.5.5 0 0 1 1 0v6a2.5 2.5 0 0 1-5 0v-6a3.5 3.5 0 0 1 7 0v6a3.5 3.5 0 0 1-7 0v-6a.5.5 0 0 1 .5-.5z"/>
          </svg>
          {content.AttachmentName}
        </span>
      </div>
    );
  }

  // Ensure content is a string before passing to PlainTextMessage
  const contentString = typeof content === 'object' ? JSON.stringify(content) : content;

  return <PlainTextMessage content={contentString} />
}

const renderTransportError = (error) => {
  if (!error || !error.message) {
    return null;
  }
  return (
    <TransportErrorMessage>
      <span>{error.message}</span>
      {error.retry && renderRetryButton(error.retry)}
    </TransportErrorMessage>
  );
}

const renderRetryButton = (callback) => {
  const onRetry = (e) => {
    e.preventDefault();
    callback();
  };

  return (
    <TransportErrorMessage.RetryButton
      href={"Retry"}
      tabIndex={0}
      onClick={onRetry}
      onKeyPress={onRetry}
    >
      Retry
    </TransportErrorMessage.RetryButton>
  );
}

const PlainTextMessage = memo((props) => {
  return (
    <Linkify properties={{ target: "_blank" }}>{props.content}</Linkify>
  );
});

const ParticipantTypingBox = styled(MessageBox)`
  > ${Body}{
    display: inline-block;
    float: ${props =>
      props.direction === Direction.Outgoing ? "right" : "left"}
`;

export const ParticipantTyping = memo((props) => {
  return (
    <ParticipantTypingBox direction={props.direction}>
      <Body direction={props.direction}>
        <TypingLoader
          color={
            props.direction === Direction.Outgoing ? "#fff" : "#000"
          }
        />
      </Body>
    </ParticipantTypingBox>
  );
});

class AttachmentMessage extends PureComponent {
  downloadAttachment = (e) => {
    e.preventDefault();
    if (!this.props.content.AttachmentId) {
      return;
    }
    this.props
      .downloadAttachment(this.props.content.AttachmentId)
      .then((blob) => {
        const link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.setAttribute("download", this.props.content.AttachmentName);
        link.click();
      });
  };

  renderContent() {
    if (this.props.content.Status === AttachmentStatus.APPROVED) {
      return (
        <a
          href={this.props.content.AttachmentName}
          onClick={this.downloadAttachment}
          onKeyPress={this.downloadAttachment}
        >
          {this.props.content.AttachmentName}
        </a>
      );
    }
    return this.props.content.AttachmentName;
  }

  render() {
    if (!this.props.content) {
      return null;
    }

    return <div>{this.renderContent()}</div>;
  }
}

export { ParticipantMessage, AttachmentMessage, MessageBox };