import React from "react";
import { ThemeProvider } from "./theme";
import styled from "styled-components";

import ChatContainer from "./components/Chat/ChatContainer";

import defaultTheme from './theme/defaultTheme';

const Page = styled.div`
  width: 390px;
  height: 600px;
  border-radius: 20px;
  font-family: ${props => props.theme.fonts.regular};
  border-collapse: collapse;
  box-shadow: 0px 4px 15px rgba(0, 0, 0, 0.2), 0px 6px 20px rgba(0, 0, 0, 0.19); /* Enhanced shadow */
  box-sizing: border-box;
  background-color: ${props => props.theme.palette.widgetbackground};
  *, *:before, *:after {
    box-sizing: inherit;
  }
`;

const AppProvider = props => {
  return (
    <ThemeProvider theme={Object.assign({}, defaultTheme, props.themeConfig)}>
      {props.children}
    </ThemeProvider>
  );
};

App.defaultProps = {
  baseCssClass: "connect-customer-interface"
};

function App({ baseCssClass, ...props }) {
  return (
    <AppProvider themeConfig={props.themeConfig || {}}>
      <Page className={baseCssClass}>
        <ChatContainer {...props}/>
      </Page>
    </AppProvider>
  );
}

export default App;