import React, { useState } from "react";
import { FormattedMessage } from "react-intl";
import styled from "styled-components";
import { getInitialContactId } from "../../ChatSession";
import { getInstanceId } from "../../ChatInitiator";

const SurveyContainer = styled.div`
  background: #ffffff;
  padding: 1rem;
  border-radius: 4px;
  margin: 1rem 0;
`;

const SurveyTitle = styled.h3`
  color: #232f3e;
  font-size: 1rem;
  margin-bottom: 1rem;
  font-weight: bold;
`;

const RatingContainer = styled.div`
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1rem;
  justify-content: center;
`;

const StarButton = styled.button`
  background: transparent;
  border: none;
  font-size: 1.5rem;
  cursor: pointer;
  color: ${(props) =>
    props.active ? (props) => props.theme.palette.header : "#d5dbdb"};
  transition: transform 0.2s, color 0.2s;

  &:hover {
    transform: scale(1.1);
    color: ${(props) => props.theme.palette.header};
  }

  &:focus {
    outline: none;
    color: ${(props) => props.theme.palette.header};
  }
`;

const FeedbackTextarea = styled.textarea`
  width: 100%;
  padding: 0.75rem;
  border: 1px solid #d5dbdb;
  border-radius: 4px;
  margin-bottom: 1rem;
  font-family: inherit;
  resize: vertical;
  min-height: 80px;

  &:focus {
    border-color: ${(props) => props.theme.palette.header};
    outline: none;
    box-shadow: 0 0 0 2px rgba(255, 153, 0, 0.2);
  }
`;

const SubmitButton = styled.button`
  background: #6e6e6e;
  color: white;
  border: none;
  padding: 0.75rem 1.1rem;
  border-radius: 15px;
  cursor: pointer;
  font-weight: bold;
  font-size: ${(props) => props.theme.globals.bodyFontSize};
  transition: background-color 0.2s;

  &:hover {
    background: ${(props) => props.theme.palette.header};
  }

  &:focus {
    outline: none;
    box-shadow: 0 0 0 2px rgba(255, 153, 0, 0.2);
  }
  &.disabled {
    opacity: 0.6;
    cursor: not-allowed;
  }
`;

// Add styled components
const LoadingSpinner = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem;

  &:before {
    content: "";
    width: 40px;
    height: 40px;
    border: 4px solid #f3f3f3;
    border-top: 4px solid #3498db;
    border-radius: 50%;
    animation: spin 1s linear infinite;
    margin-right: 1rem;
  }

  @keyframes spin {
    0% {
      transform: rotate(0deg);
    }
    100% {
      transform: rotate(360deg);
    }
  }
`;

const ThankYouMessage = styled.div`
  text-align: center;
  padding: 2rem;
  font-weight: bold;
  font-size: ${(props) => props.theme.globals.bodyFontSize};
`;

const SurveyComponent = () => {
  const [rating, setRating] = useState(0);
  const [feedback, setFeedback] = useState("");
  const initialContactId = getInitialContactId();
  const instanceId = getInstanceId(); // Direct function call
  const [isLoading, setIsLoading] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      // First lambda call to get ID
      const params = new URLSearchParams({
        InitialContactId: initialContactId,
        InstanceId: instanceId,
        AttributeName: "id",
      });

      const getIdUrl = `https://xv35bw2udagess6hc3xc2q6z7a0pxpox.lambda-url.ap-southeast-1.on.aws/?${params}`;
      console.log("Fetching ID:", params.toString());

      const idResponse = await fetch(getIdUrl, {
        method: "GET",
        headers: {
          Accept: "application/json",
        },
      });

      console.log("ID response:", idResponse);

      if (!idResponse.ok) {
        throw new Error(`HTTP error! status: ${idResponse.status}`);
      }

      const responseBody = await idResponse.json();
      console.log("Full response body:", responseBody);

      // Extract ID from attributeValue
      const id = responseBody.attributeValue;
      if (!id) {
        throw new Error("attributeValue not found in response");
      }

      console.log("ID fetched successfully:", id);

      // Second lambda call to submit survey
      const surveyUrl =
        "https://33fmwbcafobxrqokkffs26kdha0cupau.lambda-url.ap-southeast-1.on.aws/";

      // Create payload
      const surveyPayload = {
        ID: id,
        Rating: parseInt(rating),
        Feedback: feedback,
      };

      console.log("Sending survey payload:", surveyPayload);

      const surveyResponse = await fetch(surveyUrl, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json",
        },
        body: JSON.stringify(surveyPayload),
      });

      // Log the actual request that was sent
      console.log("Request body sent:", JSON.stringify(surveyPayload));

      if (!surveyResponse.ok) {
        const errorText = await surveyResponse.text();
        console.error("Survey submission failed:", errorText);
        throw new Error(
          `HTTP error! status: ${surveyResponse.status}, details: ${errorText}`
        );
      }

      const result = await surveyResponse.json();
      console.log("Survey submitted successfully:", result);
      setIsSubmitted(true);
      return result;
    } catch (error) {
      console.error("Error:", error.message);
      throw error;
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <SurveyContainer>
      {isSubmitted ? (
        <ThankYouMessage>
          <FormattedMessage
            id="survey.thankYou"
            defaultMessage="Thank you for your feedback!"
          />
        </ThankYouMessage>
      ) : isLoading ? (
        <LoadingSpinner>
          <FormattedMessage
            id="survey.submitting"
            defaultMessage="Submitting..."
          />
        </LoadingSpinner>
      ) : (
        <>
          <SurveyTitle>
            <FormattedMessage
              id="survey.title"
              defaultMessage="Please rate your experience"
            />
          </SurveyTitle>
          <form onSubmit={handleSubmit}>
            <RatingContainer>
              {[1, 2, 3, 4, 5].map((star) => (
                <StarButton
                  key={star}
                  type="button"
                  onClick={() => setRating(star)}
                  active={star <= rating}
                >
                  ★
                </StarButton>
              ))}
            </RatingContainer>
            <FeedbackTextarea
              value={feedback}
              onChange={(e) => setFeedback(e.target.value)}
              placeholder="Feedback"
            />
            <SubmitButton
              type="submit"
              disabled={!rating}
              className={!rating ? "disabled" : ""}
            >
              <FormattedMessage id="survey.submit" defaultMessage="Submit" />
            </SubmitButton>
          </form>
        </>
      )}
    </SurveyContainer>
  );
};

export default SurveyComponent;
